import { ExternalLink } from 'lucide-react'
import type { AnchorHTMLAttributes } from 'react'

import { cx } from '~/lib/cx'
import { safeHref } from '~/lib/security'
import styles from './link.module.scss'

export type LinkVariant = 'default' | 'standalone' | 'quiet'

export interface LinkProps extends AnchorHTMLAttributes<HTMLAnchorElement> {
  variant?: LinkVariant
  disabled?: boolean
  external?: boolean
}

/** Text link with safe href handling and an optional external marker. */
export function Link({
  variant = 'default',
  disabled = false,
  external = false,
  className,
  children,
  href,
  ...props
}: LinkProps) {
  const safe = disabled ? undefined : safeHref(href)

  return (
    <a
      {...props}
      href={safe}
      aria-disabled={disabled || undefined}
      rel={external ? 'noopener noreferrer' : props.rel}
      target={external ? '_blank' : props.target}
      className={cx(
        styles.root,
        variant === 'standalone' && styles.standalone,
        variant === 'quiet' && styles.quiet,
        disabled && styles.disabled,
        className,
      )}
    >
      {children}
      {external ? (
        <span className={styles.icon}>
          <ExternalLink aria-hidden />
        </span>
      ) : null}
    </a>
  )
}

@use 'styles' as vz;

.root {
  display: inline-flex;
  align-items: center;
  gap: 0.25em;
  border-radius: 2px;
  color: vz.color('primary');
  font: inherit;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  cursor: pointer;

  @include vz.hover {
    text-decoration-thickness: 2px;
  }

  @include vz.focus-ring(2px, 2px, 0.6);
}

.standalone {
  color: vz.color('foreground');
  font-weight: 600;
  text-decoration: none;

  @include vz.hover {
    color: vz.color('primary');
  }
}

.quiet {
  color: vz.color('muted-foreground');
  text-decoration: none;

  @include vz.hover {
    color: vz.color('foreground');
  }
}

.disabled {
  color: vz.color('muted-foreground');
  opacity: 0.5;
  text-decoration: none;
  pointer-events: none;
}

.icon {
  flex: none;

  svg {
    @include vz.icon(3.5);
  }
}
